    if (remoteAddedHere) {
      await execGit(['remote', 'remove', remoteName], repoPath).catch(() => {})
    }
    throw error
  }
  return {
    ...sanitizedTarget,
    remoteName,
    ...(remoteCreated ? { remoteCreated: true } : {})
